Definition tr_latch_hyp (XENV : mem -> Prop) (XENV_FP : list (Z * Z)) : Prop :=
  forall (tsp lo : Z) (ra gp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : mem),
